<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import IntroJourney from './IntroJourney.vue';
import HomeBook from './HomeBook.vue';
import type { ContentPack } from '../../core/contracts';
const props = defineProps<{ content: ContentPack; hasSave: boolean; reducedMotion: boolean }>();
const emit = defineEmits<{ start: []; continue: []; saves: []; settings: []; intro: [active: boolean] }>();
const previewIntro = new URLSearchParams(window.location.search).get('intro') === '1';
const stage = ref(previewIntro ? 0 : -1), leaving = ref(false);
const tilt = ref({x: 0, y: 0});
let timer: ReturnType<typeof setTimeout> | undefined;
const background = computed(() => props.content.assets['title-homecoming']!.url);
function move(event: PointerEvent) {
  if (props.reducedMotion || event.pointerType === 'touch') return;
  tilt.value = { x: (event.clientX / innerWidth - .5) * 2, y: (event.clientY / innerHeight - .5) * 2 };
}
watch(stage, value => emit('intro', value >= 0), { immediate: true });
function begin() { stage.value = 0; }
function openBook() { if (props.hasSave) leave(); else begin(); }
function finishJourney() { if (props.hasSave) emit('continue'); else emit('start'); }
function leave() { if (leaving.value) return; leaving.value = true; if (props.hasSave) emit('continue'); else emit('start'); }
onBeforeUnmount(() => { clearTimeout(timer); emit('intro', false); });
</script>

<template>
  <section class="overture" :class="{ still: reducedMotion, 'is-story': stage >= 0, 'is-leaving': leaving }" :style="{ '--px': tilt.x, '--py': tilt.y, '--gesture': 0 }" @pointermove="move" @pointerleave="tilt = { x: 0, y: 0 }" aria-label="百味录开场">
    <Transition name="landscape"><img :key="background" class="overture-landscape" :src="background" alt="桂花树下，长明巷的老屋亮着暖光" fetchpriority="high" /></Transition>
    <div class="overture-veil"></div><div class="overture-window" aria-hidden="true"></div>
    <div class="overture-motes" aria-hidden="true"><i v-for="n in 18" :key="n" :style="{ '--i': n }"></i></div>
    <header v-if="stage < 0" class="overture-top"><span>长明巷 <b>·</b> 秋</span><span v-if="stage >= 0" class="intro-location">{{ stage === 2 ? '归途' : '小满的房间' }}</span><button v-else @click="emit('settings')">游玩设置 ↗</button></header>
    <Transition name="chapter" mode="out-in">
      <div v-if="stage < 0" key="home" class="overture-home">
        <div class="overture-heading"><h1><span>百</span><span>味</span><span>录</span><small>长明巷<br>人间食记</small></h1></div>
        <nav class="overture-nav" aria-label="故事入口"><div><button @click="emit('saves')">存档</button><button @click="begin">重读引子</button></div></nav>
        <HomeBook :paper="content.assets['journal-paper']!.url" :reduced-motion="reducedMotion" @open="openBook" />

      </div>
      <IntroJourney v-else key="journey" :reduced-motion="reducedMotion" :home-image="content.assets['arrival-home']!.url" :title-image="content.assets['title-homecoming']!.url" :paper-image="content.assets['journal-paper']!.url" :door-image="content.assets['intro-door']!.url" :bag-image="content.assets['intro-travel-bag']!.url" @finish="finishJourney" />
    </Transition>

    <div class="overture-curtain" aria-hidden="true"><span>{{ stage < 0 ? '续上这一页' : '第一章 · 归巷' }}</span></div>
  </section>
</template>

